const TOPICS=[
 {name:'Stack & Queue',icon:'▤'},
 {name:'Monotonic Stack',icon:'⌁'},
 {name:'Sliding Window',icon:'▥'},
 {name:'Two Pointer',icon:'⇄'},
 {name:'Greedy',icon:'♜'},
 {name:'Trees',icon:'♧'},
 {name:'BST',icon:'⌂'},
 {name:'Heap',icon:'⬡'},
 {name:'Graphs',icon:'⌘'},
 {name:'Dynamic Programming',icon:'▦'},
 {name:'Backtracking Finale',icon:'✧'},
 {name:'Arrays & Basics',icon:'▦'},
 {name:'Binary Search',icon:'⌕'},
 {name:'Linked List',icon:'⛓'},
 {name:'Strings',icon:'Aa'},
 {name:'Recursion',icon:'↺'},
 {name:'Bit Manipulation',icon:'01'},
 {name:'Tries',icon:'T'},
 {name:'Sorting',icon:'⇅'}
];
const BASE=(window.A2Z_PROBLEMS?.length?window.A2Z_PROBLEMS:[]).map((p,i)=>({status:'Not Started',quality:'Independent',notes:'',custom:false,awarded:false,order:i,...p}));
const KEY='winterArc2026.v1';
const DATA_VERSION=2;
const fresh=()=>({dataVersion:DATA_VERSION,handle:'',xp:0,streak:0,lastStudy:null,problems:BASE.map(x=>({...x})),events:[],dayChecks:{},questRewards:{},weekChecks:{},mode:'auto',activeTab:'home',cf:{syncedAt:null,submissions:[],ratings:[],user:null,meta:{}},manualCF:[],achievementSeen:[],weekBoss:{},quests:[{id:'dsa',label:'Clear DSA encounters',icon:'⚔'},{id:'cf',label:'Enter the Codeforces Arena',icon:'◈'},{id:'review',label:'Revisit one old problem',icon:'↻'}]});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{state=fresh()}
function migrateProblems(){let byName=new Map((state.problems||[]).map(p=>[`${p.name}::${p.topic}`.toLowerCase(),p]));let oldSeed=(state.problems||[]).length<120||state.dataVersion!==DATA_VERSION;let merged=BASE.map(base=>{let existing=byName.get(`${base.name}::${base.topic}`.toLowerCase())||byName.get(String(base.name).toLowerCase());return existing?{...base,...existing,id:base.id,topic:base.topic,difficulty:base.difficulty,essential:base.essential,link:base.link,article:base.article,leetcode:base.leetcode,sourceId:base.sourceId,order:base.order}:{...base}});let custom=(state.problems||[]).filter(p=>p.custom&&!merged.some(x=>x.name===p.name&&x.topic===p.topic));if(oldSeed||merged.length>state.problems.length){state.problems=[...merged,...custom];state.dataVersion=DATA_VERSION;save()}}
if(!state.problems?.length)state.problems=BASE.map(x=>({...x}));
migrateProblems();
let page='home',dsaFilter='All',dsaSearch='',cfTab='overview',toastTimer, cfLoading=false;
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=()=>new Date().toLocaleDateString('en-CA');
const now=new Date(), TODAY=iso();
function exam(){return now.getFullYear()===2026&&now.getMonth()===10&&now.getDate()>=1&&now.getDate()<=20}
function mode(){return exam()?'exam':state.mode==='auto'?'normal':state.mode}
function dateLabel(){return new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(now)}
function startWeek(){let x=new Date();x.setDate(x.getDate()-((x.getDay()+6)%7));return x.toLocaleDateString('en-CA')}
function eventsToday(type){return state.events.filter(e=>e.date===TODAY&&(!type||e.type===type))}
function doneToday(){return eventsToday('dsa').length}
function cfSolvedToday(){let from=Math.floor(new Date(`${TODAY}T00:00:00`).getTime()/1000);return new Set([...(state.cf.submissions||[]),...(state.manualCF||[])].filter(s=>s.verdict==='OK'&&s.creationTimeSeconds>=from).map(s=>`${s.problem?.contestId||s.contestId}-${s.problem?.index||s.index}`)).size}
function dailyTargets(){switch(mode()){case'exam':return{dsa:0,cf:0,total:0};case'busy':return{dsa:1,cf:1,total:2};case'verybusy':return{dsa:0,cf:0,total:1};default:return{dsa:2,cf:1,total:3}}}
function dailyStatus(){if(state.dayChecks.rest?.[TODAY])return'REST DAY';if(mode()==='exam'&&doneToday()+cfSolvedToday()===0)return'EXAM ARC';let tar=dailyTargets(),dsa=Math.max(doneToday(),state.dayChecks.dsa?.[TODAY]?tar.dsa:0),cf=Math.max(cfSolvedToday()>0?1:0,state.dayChecks.cf?.[TODAY]?tar.cf:0),done=dsa+cf+(state.dayChecks.review?.[TODAY]?1:0);if(done>=tar.total&&tar.total>0)return'CLEAR';if(done>0)return'PARTIAL';return'MISSED'}
function weekData(){const d=new Date(`${startWeek()}T12:00:00`);return{start:startWeek(),d}}
function weekCount(type){const start=Math.floor(new Date(`${startWeek()}T00:00:00`).getTime()/1000);if(type==='dsa')return state.events.filter(e=>e.type==='dsa'&&new Date(e.date+'T12:00:00')>=weekData().d).length;if(type==='cf')return new Set([...(state.cf.submissions||[]),...(state.manualCF||[])].filter(s=>s.verdict==='OK'&&s.creationTimeSeconds>=start).map(s=>`${s.problem?.contestId||s.contestId}-${s.problem?.index||s.index}`)).size;return state.events.filter(e=>e.type==='dsa'&&e.quality==='Independent'&&new Date(e.date+'T12:00:00')>=weekData().d).length}
function topicStats(topic){let list=state.problems.filter(p=>p.topic===topic),must=list.filter(p=>p.essential),pool=must.length?must:list;let solved=list.filter(p=>p.status==='Solved').length,deferred=list.filter(p=>p.status==='Deferred').length,mustSolved=pool.filter(p=>p.status==='Solved').length,mustDeferred=pool.filter(p=>p.status==='Deferred').length,available=Math.max(1,pool.length-mustDeferred),allPct=list.length?Math.round(solved/list.length*100):0;return{list,solved,deferred,available,pct:Math.round(mustSolved/available*100),allPct,mustTotal:pool.length,mustSolved,mastered:mustSolved>=Math.ceil(available*.6)}}
function topicStatus(i){if(i===0)return topicStats(TOPICS[i].name).mastered?'unlocked':'active';if(!TOPICS.slice(0,i).every(t=>topicStats(t.name).mastered))return'locked';return topicStats(TOPICS[i].name).mastered?'unlocked':'active'}
function level(){return Math.floor(state.xp/250)+1}
function qualityXp(p){let diff=p.difficulty==='Hard'?70:p.difficulty==='Medium'?40:20;return Math.round(diff*(p.quality==='Independent'?1:p.quality==='Hint'?.7:.4))}
function toast(msg){let el=document.querySelector('.toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function award(amount,msg){state.xp+=amount;save();toast(`${msg} +${amount} XP`)}
function nav(){return `<aside class="side"><div class="brand"><div class="crest">❄</div><div><b>WINTER ARC</b><small>DSA COMMAND</small></div></div><div class="navlabel">OPERATIONS</div><nav class="nav">${[['home','⌂','Command Center'],['dsa','▤','DSA World'],['cf','◈','CF Arena'],['codex','▧','Arc Codex']].map(([id,ico,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="ico">${ico}</span><span>${label}</span></button>`).join('')}</nav><div class="sidefoot"><div class="arc-card"><small>✦ CURRENT ARC</small><p>Build mastery. Stack wins. Earn your 1400.</p><strong>WINTER 2026</strong></div><div class="profile"><div class="avatar">S</div><div><b>Srijan</b><small>Level ${level()} · Frost Initiate</small></div></div></div></aside>`}
function shell(content){document.getElementById('app').innerHTML=`<div class="shell" data-page="${page}">${nav()}<main class="main" data-page="${page}"><div class="topbar"><div class="crumb">WINTER ARC <span style="color:#4b5363"> / </span> <b>${({home:'COMMAND CENTER',dsa:'DSA WORLD',cf:'CODEFORCES ARENA',codex:'ARC CODEX'})[page]}</b></div><div class="topright"><span class="pill"><i class="live"></i>${exam()?'EXAM ARC ACTIVE':'SYSTEM ONLINE'}</span><span class="pill">${dateLabel()}</span><button class="iconbtn" title="Reset local progress" data-action="reset">⚙</button></div></div>${content}</main></div><div class="toast"></div>`;wire()}
function head(title,sub,eyebrow='WINTER ARC 2026'){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="date">${dateLabel().toUpperCase()}</div></div>`}
function home(){let xpPart=state.xp%250,dt=dailyTargets(),status=dailyStatus(),cur=TOPICS.findIndex((t,i)=>topicStatus(i)==='active'),current=TOPICS[Math.max(0,cur)],weekDsa=weekCount('dsa'),weekCf=weekCount('cf'),rank=state.cf.user?.rating||null,goalPct=rank?Math.max(0,Math.min(100,(rank-800)/6)):0,solvedCount=state.problems.filter(p=>p.status==='Solved').length,totalCount=state.problems.length,workPct=totalCount?Math.round(solvedCount/totalCount*100):0;
let quests=state.quests.map(q=>{let target=mode()==='verybusy'?(q.id==='review'?1:0):q.id==='dsa'?dt.dsa:q.id==='cf'?dt.cf:q.id==='review'?1:1;let count=mode()==='verybusy'&&q.id==='review'?doneToday()+cfSolvedToday():q.id==='dsa'?Math.max(doneToday(),state.dayChecks.dsa?.[TODAY]?target:0):q.id==='cf'?Math.max(cfSolvedToday(),state.dayChecks.cf?.[TODAY]?target:0):state.dayChecks[q.id]?.[TODAY]?1:0;return{...q,label:mode()==='verybusy'&&q.id==='review'?'Solve any problem':q.label,target,count,done:target===0||count>=target}});
let modeName=mode()==='verybusy'?'VERY BUSY':mode().toUpperCase();
return `${head('Your winter arc begins.','A question-first campaign to level up your DSA and Codeforces game.')}<div class="grid stats"><div class="card stat"><div><label>Arc level</label><h2>${level()} <span style="font-size:13px;color:var(--muted)">/ 20</span></h2><small>${xpPart} / 250 XP to next level</small></div><div class="stat-icon">✦</div></div><div class="card stat"><div><label>XP bank</label><h2>${state.xp.toLocaleString()}</h2><small>Quality weighted · no hours</small></div><div class="stat-icon">◈</div></div><div class="card stat"><div><label>Current streak</label><h2>${state.streak} <span style="font-size:15px">days</span></h2><small>${mode()==='exam'?'Protected through Exam Arc':'One clear day at a time'}</small></div><div class="stat-icon">♨</div></div><div class="card stat"><div><label>A2Z work done</label><h2>${workPct}%</h2><small>${solvedCount} / ${totalCount} questions solved</small></div><div class="stat-icon">⚔</div></div></div>
<div class="grid hero-grid"><section class="card hero"><div class="hero-content"><div class="eyebrow">${exam()?'📚 EXAM ARC':'❄ THE WINTER ARC'}</div><h2>${exam()?'Exams first. The arc is protected.':'Turn consistency into mastery.'}</h2><p>${exam()?'DSA quests are paused until Nov 21. Study for your exams; optional problems grant bonus XP with no streak penalty.':`Today is ${modeName} mode. Progress is measured in solved questions, solve quality, and the skill you carry forward.`}</p><div class="hero-foot"><div><b>${status}</b>DAY STATUS</div><div><b>${dt.dsa} DSA · ${dt.cf} CF</b>DAILY TARGET</div><div><b>${rank||'—'}</b>CF RATING</div></div></div></section><section class="card"><div class="section-title"><h3>Level progression</h3><span class="badge cyan">LEVEL ${level()}</span></div><div style="display:flex;align-items:baseline;gap:8px;margin:25px 0 10px"><strong style="font-size:32px">${state.xp}</strong><span class="muted">/ ${level()*250} total XP</span></div><div class="progress-track"><div class="progress-fill" style="width:${xpPart/2.5}%"></div></div><p class="muted" style="font-size:10px;margin-top:12px">${250-xpPart} XP until your next title unlock.</p><div style="border-top:1px solid var(--border);padding-top:15px;margin-top:18px;display:flex;justify-content:space-between"><span class="muted" style="font-size:10px">CF RATING JOURNEY</span><b style="font:11px 'DM Mono'">${rank||800} <span style="color:var(--dim)">→ 1400</span></b></div><div class="progress-track" style="margin-top:10px"><div class="progress-fill" style="width:${rank?goalPct:0}%;background:linear-gradient(90deg,var(--violet),var(--cyan))"></div></div></section></div>
<section class="quests"><div class="section-title"><h3>Daily Quests <span class="badge">${modeName} MODE</span></h3><div class="mode-buttons">${['normal','busy','verybusy','exam'].filter(m=>m!=='exam').map(m=>`<button class="button ghost small ${mode()===m?'selected':''}" data-action="mode" data-value="${m}">${m==='verybusy'?'VERY BUSY':m.toUpperCase()}</button>`).join('')}</div></div>${mode()==='exam'?`<div class="card exam-banner" style="padding:14px 18px;color:var(--gold)">Exam Arc is active until November 20. DSA required: <b>0</b>. No streak loss. Optional solves give bonus XP.</div>`:`<div class="grid quest-grid">${quests.filter(q=>q.target>0).map(q=>`<div class="card quest"><span class="qicon">${q.icon}</span><div><b>${q.label}</b><small>${q.target===0?'Optional bonus':`${Math.min(q.count,q.target)} / ${q.target} complete`}</small></div><button class="check ${q.done?'checked':''}" type="button" role="checkbox" aria-checked="${q.done}" aria-label="Mark ${esc(q.label)} complete" data-action="questcheck" data-id="${q.id}"></button></div>`).join('')}</div>`}</section>
<div class="grid two-col"><section class="card"><div class="section-title"><h3>Weekly Missions</h3><span class="badge">QUESTION COUNT ONLY</span></div><div class="weekly-list">${[['A2Z encounters',weekDsa,8],['Independent solves',weekCount('ind'),4],['Codeforces practice',weekCf,3]].map(([n,v,t])=>`<div class="mission"><label>${n}</label><span>${v} / ${t}</span><div class="progress-track" style="grid-column:1/-1"><div class="progress-fill" style="width:${Math.min(100,v/t*100)}%"></div></div></div>`).join('')}<div class="mission"><label>Weekly boss: ${current.name}</label><button class="button small ${state.weekBoss[startWeek()]?'secondary':''}" data-action="boss">${state.weekBoss[startWeek()]?'DEFEATED ✓':'CHALLENGE'}</button></div></div></section><section class="card"><div class="section-title"><h3>Active Dungeon</h3><button class="button ghost small" data-page="dsa">ENTER WORLD ↗</button></div><div style="display:flex;align-items:center;gap:13px;margin:19px 0"><div class="stat-icon" style="width:42px;height:42px">${current.icon}</div><div><b>${current.name}</b><small style="display:block;color:var(--muted);margin-top:4px;font-size:10px">${topicStats(current.name).solved} / ${topicStats(current.name).available} mastery encounters</small></div><span class="badge cyan right">ACTIVE</span></div><div class="progress-track"><div class="progress-fill" style="width:${topicStats(current.name).pct}%"></div></div><p class="muted" style="font-size:10px">Reach 60% mastery to unlock your next dungeon. Deferred questions leave the mastery denominator.</p></section></div>
<div class="grid two-col" style="margin-top:16px"><section class="card"><div class="section-title"><h3>Roadmap</h3><span class="badge">11 DUNGEONS</span></div><div class="roadmap">${TOPICS.map((t,i)=>`<div class="roadmap-item ${topicStatus(i)==='active'?'active':''} ${topicStats(t.name).mastered?'done':''}"><span class="roadmap-dot">${topicStats(t.name).mastered?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${t.name}</strong><small>${topicStatus(i)==='locked'?'Locked · master the previous dungeon':`${topicStats(t.name).solved}/${topicStats(t.name).available} solved · ${topicStats(t.name).pct}%`}</small></div></div>`).join('')}</div></section><section class="card"><div class="section-title"><h3>Achievements</h3><small>UNLOCK AS YOU PLAY</small></div><div class="achievements">${achievementData().map(a=>`<div class="achievement" style="opacity:${a.unlocked?1:.42}"><span>${a.icon}</span><b>${a.name}</b><small>${a.desc}</small></div>`).join('')}</div></section></div>`}
function dsaPage(){let topics=TOPICS.map((t,i)=>{let s=topicStats(t.name),st=topicStatus(i);return `<div class="topic-row"><span class="topic-num">${String(i+1).padStart(2,'0')}</span><span class="topic-name">${t.icon} &nbsp;${t.name}</span><span class="topic-state ${st}">${st==='locked'?'LOCKED':st==='active'?'ACTIVE':'UNLOCKED'}</span><span class="badge">${s.mustSolved}/${s.available} MUST</span><button class="button ghost small" data-action="topic" data-value="${esc(t.name)}">OPEN</button></div>`}).join('');let list=state.problems.filter(p=>(dsaFilter==='All'||p.status===dsaFilter)&&(dsaSearch===''||(`${p.name} ${p.topic}`).toLowerCase().includes(dsaSearch.toLowerCase()))).sort((a,b)=>TOPICS.findIndex(t=>t.name===a.topic)-TOPICS.findIndex(t=>t.name===b.topic)||Number(b.essential)-Number(a.essential)||a.order-b.order);
return `${head('DSA World','Full A2Z tracker with must-do unlocks and optional extra practice.','THE DUNGEON MAP')}<div class="card exam-banner codex" style="padding:12px 16px;margin-bottom:16px"><span style="color:var(--gold)">FULL SHEET LOADED</span> &nbsp;This tracker now includes ${BASE.length} A2Z problems. <b>Must-do</b> problems unlock the next dungeon; the rest remain trackable for extra practice and revision. <a style="color:var(--cyan)" target="_blank" href="https://takeuforward.org/prep-hub/strivers-a2z-dsa-sheet">Open current TUF sheet ↗</a></div><div class="grid two-col"><section class="card"><div class="section-title"><h3>Topic dungeons</h3><button class="button small" data-action="addproblem">+ ADD ENCOUNTER</button></div><div class="topic-list">${topics}</div><p class="muted" style="font-size:10px;margin:14px 0 0">Unlocks use must-do encounters: solve 60% of non-deferred must-do questions. Extra questions stay in the tracker for full A2Z coverage.</p></section><section class="card"><div class="section-title"><h3>Encounter inventory</h3><button class="button ghost small" data-action="import">IMPORT JSON</button></div><div class="split-head"><div class="filters">${['All','Not Started','Attempted','Solved','Revisit','Deferred'].map(x=>`<button class="button ${dsaFilter===x?'':'ghost'} small" data-action="filter" data-value="${x}">${x}</button>`).join('')}</div></div><input class="input" id="dsa-search" placeholder="Search encounter or topic…" value="${esc(dsaSearch)}" style="margin-bottom:10px"><div class="list" style="max-height:500px;overflow:auto">${list.length?list.map(problemCard).join(''):'<div class="empty">No encounters in this view. Try a different filter or add one.</div>'}</div></section></div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Progress snapshot</h3><span class="badge cyan">${state.problems.filter(p=>p.status==='Solved').length} / ${state.problems.length} SOLVED</span></div><div class="grid stats" style="margin:0">${[['Attempted',state.problems.filter(p=>p.status==='Attempted').length],['Revisit',state.problems.filter(p=>p.status==='Revisit').length],['Deferred',state.problems.filter(p=>p.status==='Deferred').length],['Must-do left',state.problems.filter(p=>p.essential&&p.status!=='Solved'&&p.status!=='Deferred').length]].map(([a,b])=>`<div><span class="muted" style="font-size:10px">${a.toUpperCase()}</span><div style="font-weight:800;font-size:22px;margin-top:5px">${b}</div></div>`).join('')}</div></div>`}
function problemCard(p){let color=p.status==='Solved'?'green':p.status==='Revisit'?'gold':p.status==='Deferred'?'red':p.status==='Attempted'?'cyan':'';let link=p.leetcode||p.link||p.article;return `<div class="card problem"><div><h4>${esc(p.name)}</h4><div class="meta"><span>${esc(p.topic)}</span><span>·</span><span>${esc(p.difficulty)}</span>${p.essential?'<span class="badge gold">MUST-DO</span>':'<span class="badge">EXTRA</span>'}<span class="badge ${color}">${esc(p.status)}</span>${p.status==='Solved'?`<span class="badge">${esc(p.quality)}</span>`:''}${link?`<a class="badge cyan" target="_blank" href="${esc(link)}">OPEN</a>`:''}</div>${p.notes?`<div class="meta" style="margin-top:7px">${esc(p.notes)}</div>`:''}</div><div class="problem-actions"><select class="select" data-action="status" data-id="${esc(p.id)}">${['Not Started','Attempted','Solved','Revisit','Deferred'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="button ghost small" data-action="editproblem" data-id="${esc(p.id)}">EDIT</button><button class="button ghost small" data-action="deleteproblem" data-id="${esc(p.id)}" title="Delete">×</button></div></div>`}
function allCFSolves(){let x=[...(state.cf.submissions||[]),...(state.manualCF||[])];let m=new Map();for(let s of x){if(s.verdict==='OK'){let p=s.problem||s,key=`${p.contestId||s.contestId}-${p.index||s.index}`;if(!m.has(key)||m.get(key).creationTimeSeconds<s.creationTimeSeconds)m.set(key,{...s,problem:p})}}return [...m.values()].sort((a,b)=>b.creationTimeSeconds-a.creationTimeSeconds)}
function cfPage(){let r=state.cf.user?.rating||0,max=state.cf.user?.maxRating||0,all=allCFSolves(),rankInfo=state.cf.user?.rank||'Connect handle';let latest=state.cf.submissions||[];let tags=[...new Set(all.flatMap(s=>s.problem.tags||[]))];let ratings=state.cf.ratings||[];let svg=ratingSvg(ratings);
return `${head('Codeforces Arena','Live public profile data with your private solve-quality notes.','THE COMPETITIVE CIRCUIT')}<div class="grid arena-hero"><section class="card"><div class="split-head"><div><div class="eyebrow">RATING JOURNEY</div><div class="rating-number" style="color:${ratingColor(r)}">${r||'—'}</div><div class="rating-caption">${esc(rankInfo)} · peak ${max||'—'}</div></div><span class="badge cyan">GOAL 1400</span></div>${svg}<div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,Math.max(0,(r-800)/6))}%;background:linear-gradient(90deg,var(--violet),var(--cyan))"></div></div><div class="split-head" style="margin:9px 0 0"><span class="muted" style="font-size:10px">${r?`${Math.max(0,1400-r)} rating points to goal`:'Connect your handle to start the journey'}</span><span class="muted" style="font:10px 'DM Mono'">${r} / 1400</span></div></section><section class="card"><div class="section-title"><h3>Connect profile</h3><span class="badge">PUBLIC API</span></div><p class="muted" style="font-size:11px;line-height:1.6">Your handle is enough. No password or API key. Data comes from Codeforces public APIs.</p><form class="inline-form" data-action="syncform"><input id="handle-input" class="input" type="text" placeholder="Codeforces handle" value="${esc(state.handle)}" autocomplete="off" spellcheck="false"><button class="button" data-action="sync">${cfLoading?'SYNCING…':'SYNC'}</button></form><button class="button ghost small" style="margin-top:9px" data-action="manualcf">+ LOG A PROBLEM</button>${state.cf.syncedAt?`<p class="muted" style="font-size:9px;margin-top:12px">Last sync ${new Date(state.cf.syncedAt).toLocaleString()}</p>`:''}</section></div><div class="grid stats" style="margin-top:16px"><div class="card stat"><div><label>Problems solved</label><h2>${all.length}</h2><small>Unique accepted problems</small></div><div class="stat-icon">✓</div></div><div class="card stat"><div><label>Submissions</label><h2>${latest.length}</h2><small>Synced submission history</small></div><div class="stat-icon">↗</div></div><div class="card stat"><div><label>Contests</label><h2>${ratings.length}</h2><small>Rated contests</small></div><div class="stat-icon">♜</div></div><div class="card stat"><div><label>Tags explored</label><h2>${tags.length}</h2><small>Distinct problem tags</small></div><div class="stat-icon">⌘</div></div></div><section class="card"><div class="tabbar">${[['overview','Overview'],['solved','Solved problems'],['submissions','Submissions'],['contests','Rating history'],['tags','Tags & stats']].map(([id,label])=>`<button class="tab ${cfTab===id?'active':''}" data-action="cftab" data-value="${id}">${label}</button>`).join('')}</div>${cfContent(all,latest,ratings,tags)}</section>`}
function ratingColor(r){if(r>=2400)return'#ff5555';if(r>=2100)return'#ff8a3d';if(r>=1900)return'#c66bff';if(r>=1600)return'#b08cff';if(r>=1400)return'#f7bd4c';if(r>=1200)return'#71dfa0';return'#bbc4d4'}
function ratingSvg(ratings){if(!ratings.length)return `<div class="empty" style="height:90px">Rating chart appears after syncing a handle.</div>`;let values=ratings.slice(-25).map(x=>x.newRating),min=Math.min(...values,800),max=Math.max(...values,1400),w=600,h=105,p=8;let pts=values.map((v,i)=>`${p+i*(w-p*2)/Math.max(1,values.length-1)},${h-p-(v-min)/(max-min||1)*(h-p*2)}`).join(' ');let y1400=h-p-(1400-min)/(max-min||1)*(h-p*2);return `<svg class="journey" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="rg" x1="0" x2="1"><stop stop-color="#a18cff"/><stop offset="1" stop-color="#63e6d0"/></linearGradient></defs><line x1="0" y1="${Math.max(0,Math.min(h,y1400))}" x2="${w}" y2="${Math.max(0,Math.min(h,y1400))}" stroke="#f4c36a66" stroke-dasharray="4 5"/><polyline points="${pts}" fill="none" stroke="url(#rg)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><text x="${w-32}" y="${Math.max(11,Math.min(h-2,y1400-4))}" fill="#f4c36a" font-size="10">1400</text></svg>`}
function cfContent(all,subs,ratings,tags){if(!state.handle&&!state.manualCF.length)return `<div class="empty">Connect your Codeforces handle to pull solves, verdicts, tags and contest ratings.<br>Use “Log a problem” to record offline practice.</div>`;if(cfTab==='overview')return `<div class="grid two-col"><div><h3 style="font-size:12px">Recent accepted problems</h3><div class="list">${all.slice(0,5).map(cfProblem).join('')||'<div class="empty">No accepted problems yet.</div>'}</div></div><div><h3 style="font-size:12px">Latest submissions</h3><div class="list">${subs.slice(0,5).map(submissionCard).join('')||'<div class="empty">No submissions loaded.</div>'}</div></div></div>`;if(cfTab==='solved')return `<div class="list">${all.length?all.map(cfProblem).join(''):'<div class="empty">No accepted problems found.</div>'}</div>`;if(cfTab==='submissions')return `<div class="list">${subs.length?subs.slice(0,120).map(submissionCard).join(''):'<div class="empty">Connect your profile to load submissions.</div>'}</div>`;if(cfTab==='contests')return `<div class="list">${ratings.length?ratings.slice().reverse().map(x=>`<div class="card problem"><div><h4>${esc(x.contestName)}</h4><div class="meta">${new Date(x.ratingUpdateTimeSeconds*1000).toLocaleDateString()} · rank ${x.rank}</div></div><div style="text-align:right"><strong style="color:${ratingColor(x.newRating)}">${x.newRating}</strong><div class="meta">${x.newRating-x.oldRating>=0?'+':''}${x.newRating-x.oldRating}</div></div></div>`).join(''):'<div class="empty">Rating history appears after sync.</div>'}</div>`;return `<div class="achievements">${tags.map(t=>`<span class="badge">${esc(t)}</span>`).join('')||'<span class="muted">No tag data loaded.</span>'}</div><div class="cf-stats">${difficultyStats(all).map(([d,c])=>`<div class="card"><strong>${c}</strong><small>${d} problems solved</small></div>`).join('')}</div>`}
function cfProblem(s){let p=s.problem||{},key=`${p.contestId}-${p.index}`,handleMeta=state.cf.meta?.[key]||{};return `<div class="card problem"><div><h4><a target="_blank" rel="noreferrer" style="color:var(--text);text-decoration:none" href="https://codeforces.com/contest/${p.contestId}/problem/${p.index}">${p.contestId}${p.index} · ${esc(p.name)}</a></h4><div class="meta">${p.rating?`<span>${p.rating}</span>`:''}${(p.tags||[]).slice(0,4).map(t=>`<span class="badge">${esc(t)}</span>`).join('')}<span class="badge green">SOLVED</span>${handleMeta.quality?`<span class="badge cyan">${esc(handleMeta.quality)}</span>`:''}</div>${handleMeta.notes?`<div class="meta" style="margin-top:6px">${esc(handleMeta.notes)}</div>`:''}</div><div class="problem-actions"><button class="button ghost small" data-action="cfmeta" data-key="${key}" data-name="${esc(p.name)}" data-rating="${p.rating||''}">NOTES</button>${s.entryId?`<button class="button ghost small" data-action="editmanualcf" data-id="${s.entryId}">EDIT</button><button class="button ghost small" data-action="deletemanualcf" data-id="${s.entryId}">×</button>`:''}</div></div>`}
function submissionCard(s){let p=s.problem||{},ok=s.verdict==='OK';return `<div class="card problem"><div><h4>${p.contestId||''}${p.index||''} · ${esc(p.name||'Problem')}</h4><div class="meta"><span class="badge ${ok?'green':'red'}">${esc(s.verdict||'UNKNOWN')}</span><span>${new Date((s.creationTimeSeconds||0)*1000).toLocaleString()}</span>${p.rating?`<span>${p.rating}</span>`:''}<span>${(p.tags||[]).slice(0,3).map(esc).join(' · ')}</span></div></div><span class="muted" style="font:10px 'DM Mono'">#${s.id||'manual'}</span></div>`}
function difficultyStats(all){return [['800–999',all.filter(s=>(s.problem.rating||0)<1000).length],['1000–1199',all.filter(s=>s.problem.rating>=1000&&s.problem.rating<1200).length],['1200–1399',all.filter(s=>s.problem.rating>=1200&&s.problem.rating<1400).length],['1400+',all.filter(s=>s.problem.rating>=1400).length]]}
function codex(){return `${head('The Arc Codex','The rules that keep progress honest, flexible, and question-first.','FIELD MANUAL')}<div class="grid rule-grid"><section class="card codex"><div class="eyebrow">01 · THE SCORE</div><h3>Questions are the unit. Hours do not score.</h3><p>Track problems attempted, solved, revisited, and the quality of each solve. Difficulty and independence determine XP. A timer never awards points.</p><ul><li>Independent: 100% XP</li><li>Used a hint, then solved: 70% XP</li><li>Needed the editorial: 40% XP</li><li>Easy 20 XP · Medium 40 XP · Hard 70 XP baseline</li><li>Independent solve rate is a core mastery metric.</li></ul></section><section class="card codex"><div class="eyebrow">02 · DAILY QUESTS</div><h3>Scale the quest to the day.</h3><ul><li><b>Normal:</b> 2–3 DSA + 1 Codeforces</li><li><b>Busy:</b> 1 DSA + 1 Codeforces</li><li><b>Very busy:</b> 1 problem total</li><li><b>Exam Arc:</b> 0 required</li><li>Clear · Partial · Missed · Rest Day</li><li>Partial progress is not failure. Rest can be intentional.</li></ul></section><section class="card codex"><div class="eyebrow">03 · WHEN STUCK</div><h3>Think first. Then take a useful hint.</h3><p>Give a problem a focused 15–20 minute attempt. If stuck, look for a hint, close it, and retry. Use an editorial only after trying again. Log the quality honestly; returning later is part of the process.</p><p>Skipped or deferred problems go into the revisit inventory. Defer freely to unlock the next topic after reaching 60% mastery of the remaining set.</p></section><section class="card codex"><div class="eyebrow">04 · WEEKLY MISSIONS</div><h3>Recover across the week.</h3><p>Weekly targets are counts, never hours. A sample normal week: 8 A2Z problems, 4 independent solves, 3 Codeforces problems, plus a weekly boss. The boss is a challenge, not a punishment.</p><p>A rough day does not erase the week. Partial is still progress.</p></section></div><section class="card exam-banner codex" style="margin-top:16px"><div class="eyebrow" style="color:var(--gold)">05 · NOVEMBER 1–20 · EXAM ARC</div><h3>Exam mode is protected campaign time.</h3><p>Required DSA count: <b style="color:var(--gold)">0</b>. Focus on exams. Optional problems earn bonus XP. Missed DSA creates no streak punishment or lost XP. The regular Winter Arc resumes November 21, 2026.</p></section><section class="card codex" style="margin-top:16px"><div class="eyebrow">06 · WINTER ARC ROUTE</div><h3>Dungeon sequence</h3><p>${TOPICS.map(t=>esc(t.name)).join(' → ')}.</p><p>Unlock the next dungeon at 60% mastery among non-deferred encounters. A boss battle may be attempted weekly for bonus XP. Local browser storage keeps your quest state on this device.</p></section><section class="card" style="margin-top:16px"><div class="section-title"><h3>Mission settings</h3><span class="badge">SAVED ON THIS DEVICE</span></div><div class="grid two-col"><div><p class="muted" style="font-size:11px">Export your progress or restore it on another browser.</p><button class="button ghost small" data-action="export">EXPORT SAVE FILE</button><label class="button ghost small" style="margin-left:7px;cursor:pointer">IMPORT SAVE FILE<input type="file" accept="application/json" data-action="saveimport" hidden></label></div><div><p class="muted" style="font-size:11px">Daily quest mode can follow the arc default or your schedule.</p><select class="select" data-action="selectmode">${['auto','normal','busy','verybusy'].map(x=>`<option value="${x}" ${state.mode===x?'selected':''}>${x==='verybusy'?'Very busy':x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div></div></section>`}
function achievementData(){let solved=state.problems.filter(p=>p.status==='Solved').length,ind=state.problems.filter(p=>p.status==='Solved'&&p.quality==='Independent').length,cf=allCFSolves().length,mastered=TOPICS.filter(t=>topicStats(t.name).mastered).length;return [{icon:'❄',name:'First Frost',desc:'Solve 1 encounter',unlocked:solved>=1},{icon:'⚔',name:'Five Wins',desc:'Solve 5 encounters',unlocked:solved>=5},{icon:'✦',name:'Clean Technique',desc:'5 independent solves',unlocked:ind>=5},{icon:'♜',name:'Circuit Rookie',desc:'Solve a CF problem',unlocked:cf>=1},{icon:'🗝',name:'Dungeon Master',desc:'Master a topic',unlocked:mastered>=1},{icon:'🔥',name:'On a Roll',desc:'3 day streak',unlocked:state.streak>=3}]}
function render(){let content=page==='home'?home():page==='dsa'?dsaPage():page==='cf'?cfPage():codex();shell(content)}
function modal(title,desc,body,submit='SAVE',action='save'){document.querySelector('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><section class="modal"><h2>${title}</h2><p>${desc}</p><form class="form" id="modal-form">${body}<div class="modal-actions"><button type="button" class="button ghost" data-action="closemodal">CANCEL</button><button class="button">${submit}</button></div></form></section></div>`);document.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))e.currentTarget.remove()});document.querySelector('.modal [data-action="closemodal"]').addEventListener('click',()=>document.querySelector('.modal-backdrop')?.remove());document.querySelector('#modal-form').addEventListener('submit',e=>{e.preventDefault();handleModal(action,new FormData(e.currentTarget))})}
function problemModal(p){let isEdit=!!p;modal(isEdit?'Edit encounter':'Add encounter',isEdit?'Update its topic, status and notes.':'Add a problem to your local A2Z tracker.',`<input type="hidden" name="id" value="${esc(p?.id||'')}"><div class="field"><label>PROBLEM NAME</label><input required class="input" name="name" value="${esc(p?.name||'')}"></div><div class="form-row"><div class="field"><label>TOPIC</label><select class="select" name="topic" style="width:100%">${TOPICS.map(t=>`<option ${p?.topic===t.name?'selected':''}>${esc(t.name)}</option>`).join('')}<option ${p&&!TOPICS.some(t=>t.name===p.topic)?'selected':''}>${esc(p&&!TOPICS.some(t=>t.name===p.topic)?p.topic:'Custom Topic')}</option></select></div><div class="field"><label>DIFFICULTY</label><select class="select" name="difficulty" style="width:100%">${['Easy','Medium','Hard'].map(x=>`<option ${p?.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="form-row"><div class="field"><label>STATUS</label><select class="select" name="status" style="width:100%">${['Not Started','Attempted','Solved','Revisit','Deferred'].map(x=>`<option ${p?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>SOLVE QUALITY</label><select class="select" name="quality" style="width:100%">${['Independent','Hint','Editorial'].map(x=>`<option ${p?.quality===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>NOTES</label><textarea class="textarea" name="notes" placeholder="Approach, mistake, revisit cue…">${esc(p?.notes||'')}</textarea></div>`,isEdit?'UPDATE':'ADD ENCOUNTER',isEdit?'editproblem':'newproblem')}
function handleModal(action,fd){let vals=Object.fromEntries(fd.entries());if(action==='newproblem'||action==='editproblem'){let obj={...(state.problems.find(x=>x.id===vals.id)||{}),...vals,id:vals.id||`custom-${crypto.randomUUID()}`,custom:vals.id?state.problems.find(x=>x.id===vals.id)?.custom:true,order:999,awarded:false};let old=state.problems.find(x=>x.id===obj.id);if(old){Object.assign(old,obj);setProblemStatus(old,vals.status,vals.quality,true)}else{state.problems.push(obj);if(vals.status==='Solved')setProblemStatus(obj,'Solved',vals.quality)}save();document.querySelector('.modal-backdrop')?.remove();render();toast('Encounter saved');return}if(action==='manualcf'){let name=vals.name.trim(), id=vals.problemId.trim();let problem={contestId:Number(id.match(/^\d+/)?.[0]||0),index:id.match(/[A-Z]+$/)?.[0]||'A',name,rating:Number(vals.rating)||undefined,tags:vals.tags.split(',').map(x=>x.trim()).filter(Boolean)};state.manualCF.push({id:'manual',verdict:'OK',creationTimeSeconds:Math.floor(Date.now()/1000),problem});state.cf.meta ||= {};state.cf.meta[`${problem.contestId}-${problem.index}`]={quality:vals.quality,notes:vals.notes};save();document.querySelector('.modal-backdrop')?.remove();render();toast('Arena problem logged');return}if(action==='cfmeta'){state.cf.meta ||= {};state.cf.meta[vals.key]={quality:vals.quality,notes:vals.notes};save();document.querySelector('.modal-backdrop')?.remove();render();toast('Solve notes saved');return}if(action==='boss'){state.weekBoss[startWeek()]=true;state.xp+=50;save();document.querySelector('.modal-backdrop')?.remove();render();toast('Boss defeated · +50 XP');return}}
function setProblemStatus(p,status,quality=p.quality,quiet=false){let prev=p.status,ti=TOPICS.findIndex(t=>t.name===p.topic);if(ti>0&&topicStatus(ti)==='locked'&&prev!==status){toast('This dungeon is locked. Master or defer enough encounters in the previous dungeon first.');if(!quiet)render();return}let oldXp=state.events.find(e=>e.type==='dsa'&&e.problemId===p.id)?.xp||qualityXp(p);p.status=status;p.quality=quality;if(status==='Solved'&&prev!=='Solved'&&!p.awarded){let xp=qualityXp(p);p.awarded=true;state.events.push({type:'dsa',problemId:p.id,date:TODAY,quality, xp});state.xp+=xp;let last=state.lastStudy;if(last!==TODAY){state.streak=last===new Date(Date.now()-86400000).toLocaleDateString('en-CA')?state.streak+1:1;state.lastStudy=TODAY}if(!quiet){save();render();toast(`Encounter cleared · +${xp} XP`)}}else if(status!=='Solved'&&prev==='Solved'&&p.awarded){p.awarded=false;state.xp=Math.max(0,state.xp-oldXp);state.events=state.events.filter(e=>!(e.type==='dsa'&&e.problemId===p.id));save();if(!quiet){render();toast(`Encounter XP removed · -${oldXp} XP`)}}else{save();if(!quiet)render()}}
function openManualCF(existing){let p=existing?.problem||{},id=p.contestId?`${p.contestId}${p.index}`:'',q=state.cf.meta?.[`${p.contestId}-${p.index}`]||{};modal(existing?'Edit Arena solve':'Log an Arena solve',existing?'Update this locally entered accepted problem.':'Record an accepted Codeforces problem and the quality you used.',`${existing?`<input type="hidden" name="entryId" value="${esc(existing.entryId)}">`:''}<div class="form-row"><div class="field"><label>CONTEST + INDEX</label><input class="input" name="problemId" placeholder="e.g. 4A" value="${esc(id)}" required></div><div class="field"><label>RATING (OPTIONAL)</label><input class="input" name="rating" type="number" placeholder="800" value="${p.rating||''}"></div></div><div class="field"><label>PROBLEM NAME</label><input class="input" name="name" value="${esc(p.name||'')}" required></div><div class="field"><label>TAGS, COMMA SEPARATED</label><input class="input" name="tags" value="${esc((p.tags||[]).join(', '))}" placeholder="greedy, math"></div><div class="field"><label>SOLVE QUALITY</label><select class="select" name="quality" style="width:100%">${['Independent','Hint','Editorial'].map(x=>`<option ${q.quality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>NOTES</label><textarea class="textarea" name="notes">${esc(q.notes||'')}</textarea></div>`,'SAVE PROBLEM',existing?'editmanualcf':'manualcf')}
function openCFMeta(key,name,rating){let m=state.cf.meta?.[key]||{};modal(`Solve notes · ${esc(name)}`,'Record your approach and how independently you solved it.',`<input type="hidden" name="key" value="${esc(key)}"><div class="field"><label>SOLVE QUALITY</label><select class="select" name="quality" style="width:100%">${['Independent','Hint','Editorial'].map(x=>`<option ${m.quality===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>NOTES</label><textarea class="textarea" name="notes" placeholder="What did you learn?">${esc(m.notes||'')}</textarea></div>`,'SAVE NOTES','cfmeta')}
async function syncCF(){let input=document.querySelector('#handle-input'),h=(input?.value||state.handle).trim();if(!h){toast('Enter a Codeforces handle first');input?.focus();return}state.handle=h;save();cfLoading=true;render();try{let base='https://codeforces.com/api',get=async path=>{let res=await fetch(`${base}/${path}`);if(!res.ok)throw Error('Codeforces API request failed');let json=await res.json();if(json.status!=='OK')throw Error(json.comment||'Profile lookup failed');return json.result};let [u,s,r]=await Promise.all([get(`user.info?handles=${encodeURIComponent(h)}`),get(`user.status?handle=${encodeURIComponent(h)}`),get(`user.rating?handle=${encodeURIComponent(h)}`)]);state.cf={...state.cf,user:u[0],submissions:s,ratings:r,syncedAt:new Date().toISOString()};save();toast(`Synced ${h}`)}catch(e){save();toast(`Sync failed: ${e.message}. Your handle is still saved.`)}finally{cfLoading=false;render()}}
function editProblem(id){let p=state.problems.find(x=>x.id===id);if(!p)return;let i=TOPICS.findIndex(t=>t.name===p.topic);if(i>0&&topicStatus(i)==='locked'){toast('This dungeon is locked until the earlier route is mastered.');return}problemModal(p)}
function act(el){let a=el.dataset.action,id=el.dataset.id,val=el.dataset.value;if(el.dataset.page){page=el.dataset.page;render();return}if(a==='mode'){state.mode=val;save();render()}else if(a==='questcheck'){let qid=el.dataset.id;state.dayChecks[qid]||={};state.questRewards||={};let rewardKey=`${TODAY}:${qid}`,checked=el.getAttribute('aria-checked')!=='true';if(checked){state.dayChecks[qid][TODAY]=true;if(!state.questRewards[rewardKey]){state.questRewards[rewardKey]=8;state.xp+=8;toast('Quest bonus · +8 XP')}}else{delete state.dayChecks[qid][TODAY];let reward=Number(state.questRewards[rewardKey])||(state.questRewards[rewardKey]===true?8:0);if(reward){state.xp=Math.max(0,state.xp-reward);toast(`Quest bonus removed · −${reward} XP`)}delete state.questRewards[rewardKey]}save();render()}else if(a==='status'){let p=state.problems.find(x=>x.id===id);if(!p)return;let quality=p.quality;if(val==='Solved'&&p.status!=='Solved'){quality=prompt('Solve quality? Enter Independent, Hint, or Editorial.','Independent')||'Independent';quality=['Independent','Hint','Editorial'].includes(quality)?quality:'Independent'}setProblemStatus(p,val,quality)}else if(a==='topic'){let i=TOPICS.findIndex(t=>t.name===val);if(topicStatus(i)==='locked'){toast('Dungeon locked · reach 60% mastery in each earlier dungeon');return}dsaFilter='All';dsaSearch='';render();setTimeout(()=>{let cards=document.querySelectorAll('.topic-row');cards[i]?.scrollIntoView({behavior:'smooth',block:'center'})},20)}else if(a==='filter'){dsaFilter=val;render()}else if(a==='addproblem')problemModal(null);else if(a==='editproblem')editProblem(id);else if(a==='deleteproblem'){let p=state.problems.find(x=>x.id===id);if(p?.custom){if(confirm(`Delete “${p.name}”?`)){state.problems=state.problems.filter(x=>x.id!==id);save();render()}}else{if(confirm('Remove this encounter from your personal tracker?')){state.problems=state.problems.filter(x=>x.id!==id);save();render()}}}else if(a==='import'){modal('Import encounters','Paste a JSON array of problems. Each item needs a name and topic; difficulty, status and notes are optional.',`<div class="field"><label>JSON ARRAY</label><textarea class="textarea" name="json" required placeholder='[{"name":"Example problem","topic":"Graphs","difficulty":"Medium"}]'></textarea></div>`,'IMPORT','importproblems')}else if(a==='sync')syncCF();else if(a==='cftab'){cfTab=val;render()}else if(a==='manualcf')openManualCF();else if(a==='cfmeta')openCFMeta(el.dataset.key,el.dataset.name,el.dataset.rating);else if(a==='boss'){let topic=TOPICS.find((t,i)=>topicStatus(i)==='active')||TOPICS[0],p=topicStats(topic.name).list.find(x=>x.status!=='Solved'&&x.status!=='Deferred');if(!p){toast('Clear or defer an encounter before challenging this boss');return}modal(`${topic.name} · Dungeon boss`,`Solve or explain this encounter: ${p.name}`,`<p class="muted">Pick the boss challenge as complete after solving it or explaining the core approach without notes.</p><label style="display:flex;gap:9px;align-items:center;font-size:11px"><input type="checkbox" name="complete" required> I cleared the boss challenge</label>`,'CLAIM 50 XP','boss')}else if(a==='closemodal')document.querySelector('.modal-backdrop')?.remove();else if(a==='reset'){if(confirm('Reset all Winter Arc data stored on this device? This cannot be undone.')){localStorage.removeItem(KEY);state=fresh();page='home';render()}}else if(a==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='winter-arc-save.json';link.click();URL.revokeObjectURL(u)} }
function handleModal(action,fd){let vals=Object.fromEntries(fd.entries());if(action==='importproblems'){try{let arr=JSON.parse(vals.json);if(!Array.isArray(arr))throw Error('Expected a JSON array');arr.forEach((x,i)=>{if(!x.name||!x.topic)return;state.problems.push({id:`import-${crypto.randomUUID()}`,name:String(x.name),topic:String(x.topic),difficulty:['Easy','Medium','Hard'].includes(x.difficulty)?x.difficulty:'Medium',status:['Not Started','Attempted','Solved','Revisit','Deferred'].includes(x.status)?x.status:'Not Started',quality:['Independent','Hint','Editorial'].includes(x.quality)?x.quality:'Independent',notes:String(x.notes||''),custom:true,order:900+i,awarded:false})});save();document.querySelector('.modal-backdrop')?.remove();render();toast('Encounter list imported')}catch(e){toast(`Import failed: ${e.message}`)}return}if(action==='saveimport'){try{let obj=JSON.parse(vals.json);state={...fresh(),...obj};save();page='home';document.querySelector('.modal-backdrop')?.remove();render();toast('Save restored')}catch(e){toast('Could not restore save file')}return}if(action==='selectmode'){state.mode=vals.mode;save();render();return}if(action==='boss'){if(vals.complete){state.weekBoss[startWeek()]=true;state.xp+=50;save();document.querySelector('.modal-backdrop')?.remove();render();toast('Boss defeated · +50 XP')}return}if(action==='newproblem'||action==='editproblem'){let current=state.problems.find(x=>x.id===vals.id),obj={...(current||{}),...vals,id:vals.id||`custom-${crypto.randomUUID()}`,custom:current?current.custom:true,order:current?.order??999,awarded:current?.awarded||false};if(current){Object.assign(current,obj);setProblemStatus(current,vals.status,vals.quality,true)}else{state.problems.push(obj);if(vals.status==='Solved')setProblemStatus(obj,'Solved',vals.quality,true)}save();document.querySelector('.modal-backdrop')?.remove();render();toast('Encounter saved');return}if(action==='manualcf'){let name=vals.name.trim(),id=vals.problemId.trim(),problem={contestId:Number(id.match(/^\d+/)?.[0]||0),index:id.match(/[A-Z]+$/)?.[0]||'A',name,rating:Number(vals.rating)||undefined,tags:vals.tags.split(',').map(x=>x.trim()).filter(Boolean)};state.manualCF.push({id:'manual',verdict:'OK',creationTimeSeconds:Math.floor(Date.now()/1000),problem});state.cf.meta||={};state.cf.meta[`${problem.contestId}-${problem.index}`]={quality:vals.quality,notes:vals.notes};state.xp+=qualityXp({difficulty:problem.rating>=1600?'Hard':problem.rating>=1100?'Medium':'Easy',quality:vals.quality});save();document.querySelector('.modal-backdrop')?.remove();render();toast('Arena problem logged');return}if(action==='cfmeta'){state.cf.meta||={};state.cf.meta[vals.key]={quality:vals.quality,notes:vals.notes};save();document.querySelector('.modal-backdrop')?.remove();render();toast('Solve notes saved')}}
function wire(){document.getElementById('app').onclick=e=>{let x=e.target.closest('[data-page]');if(x){e.preventDefault();let next=x.dataset.page;if(['home','dsa','cf','codex'].includes(next)){page=next;render()}return}};document.querySelector('[data-action="syncform"]')?.addEventListener('submit',e=>{e.preventDefault();syncCF()});document.querySelectorAll('[data-action]').forEach(x=>{if(x.dataset.action==='syncform')return;if(x.dataset.action==='questcheck')x.addEventListener('click',()=>act(x));else if(x.dataset.action==='status'||x.dataset.action==='selectmode'||x.dataset.action==='saveimport')x.addEventListener('change',()=>{if(x.dataset.action==='selectmode'){state.mode=x.value;save();render()}else if(x.dataset.action==='saveimport'){let f=x.files[0];if(f){let r=new FileReader();r.onload=()=>{try{state={...fresh(),...JSON.parse(r.result)};migrateProblems();save();render();toast('Save restored')}catch{toast('Invalid save file')}};r.readAsText(f)}}else act(x)});else x.addEventListener('click',e=>{if(x.dataset.action==='import'||x.dataset.action==='sync'){e.preventDefault()}act(x)})});let search=document.querySelector('#dsa-search');search?.addEventListener('input',()=>{dsaSearch=search.value;let pos=search.selectionStart;let list=document.querySelector('.list[style*="max-height"]');if(list){let filtered=state.problems.filter(p=>(dsaFilter==='All'||p.status===dsaFilter)&&(dsaSearch===''||(`${p.name} ${p.topic}`).toLowerCase().includes(dsaSearch.toLowerCase()))).sort((a,b)=>TOPICS.findIndex(t=>t.name===a.topic)-TOPICS.findIndex(t=>t.name===b.topic)||Number(b.essential)-Number(a.essential)||a.order-b.order);list.innerHTML=filtered.map(problemCard).join('')||'<div class="empty">No encounters in this view.</div>';list.querySelectorAll('[data-action]').forEach(x=>x.addEventListener('click',()=>act(x)));list.querySelectorAll('select[data-action=status]').forEach(x=>x.addEventListener('change',()=>act(x)));search.focus();search.setSelectionRange(pos,pos)}});document.querySelectorAll('.modal [data-action="closemodal"]').forEach(x=>x.onclick=()=>document.querySelector('.modal-backdrop')?.remove());}
const baseHandleModal=handleModal;
handleModal=function(action,fd){let vals=Object.fromEntries(fd.entries());if(action==='manualcf'||action==='editmanualcf'){let prob=vals.problemId.trim(),problem={contestId:Number(prob.match(/^\d+/)?.[0]||0),index:prob.match(/[A-Z]+$/)?.[0]||'A',name:vals.name.trim(),rating:Number(vals.rating)||undefined,tags:vals.tags.split(',').map(x=>x.trim()).filter(Boolean)};state.cf.meta||={};state.cf.meta[`${problem.contestId}-${problem.index}`]={quality:vals.quality,notes:vals.notes};if(action==='editmanualcf'){let old=state.manualCF.find(x=>x.entryId===vals.entryId);if(old){old.problem=problem;old.creationTimeSeconds=Math.floor(Date.now()/1000)}}else{state.manualCF.push({entryId:crypto.randomUUID(),id:'manual',verdict:'OK',creationTimeSeconds:Math.floor(Date.now()/1000),problem});state.xp+=qualityXp({difficulty:problem.rating>=1600?'Hard':problem.rating>=1100?'Medium':'Easy',quality:vals.quality})}save();document.querySelector('.modal-backdrop')?.remove();render();toast(action==='manualcf'?'Arena problem logged':'Arena problem updated');return}baseHandleModal(action,fd)};
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='editmanualcf'){e.preventDefault();let p=state.manualCF.find(x=>x.entryId===el.dataset.id);if(p)openManualCF(p)}else if(el.dataset.action==='deletemanualcf'){e.preventDefault();if(confirm('Delete this manually logged Codeforces problem?')){state.manualCF=state.manualCF.filter(x=>x.entryId!==el.dataset.id);save();render()}}});
render();
